  "portfolio/about.html": "<!doctype html>\n<html lang=\"ko\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>자기소개</title>\n    <meta\n      name=\"description\"\n      content=\"HTML · CSS · JavaScript로 만든 개인 사이트\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <script src=\"./script.js\" defer></script>\n  </head>\n  <body>\n    <header>\n      <strong>MY PORTFOLIO</strong>\n      <nav aria-label=\"프로젝트\">\n        <a href=\"./index.html\">홈</a>\n        <a href=\"./about.html\">소개</a>\n        <a href=\"./projects.html\">프로젝트</a>\n      </nav>\n    </header>\n    <main>\n      <section class=\"profile\">\n        <h1>자기소개</h1>\n        <p id=\"intro\" aria-live=\"polite\">웹 개발 학습 중</p>\n        <button id=\"change\" type=\"button\">소개 바꾸기</button>\n      </section>\n      <section id=\"interests\">\n        <h2>관심 분야</h2>\n        <p>웹 개발과 디자인</p>\n      </section>\n    </main>\n    <footer>2026 · 웹서비스개발</footer>\n  </body>\n</html>\n",
