  "portfolio/en/about.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>About Me</title>\n    <meta\n      name=\"description\"\n      content=\"A personal site built with HTML, CSS and JavaScript\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <script src=\"./script.js\" defer></script>\n  </head>\n  <body>\n    <header>\n      <strong>MY PORTFOLIO</strong>\n      <nav aria-label=\"Projects\">\n        <a href=\"./index.html\">Home</a>\n        <a href=\"./about.html\">About</a>\n        <a href=\"./projects.html\">Projects</a>\n      </nav>\n    </header>\n    <main>\n      <section class=\"profile\">\n        <h1>About Me</h1>\n        <p id=\"intro\" aria-live=\"polite\">Learning web development.</p>\n        <button id=\"change\" type=\"button\">Change Introduction</button>\n      </section>\n      <section id=\"interests\">\n        <h2>Interests</h2>\n        <p>Web development and design</p>\n      </section>\n    </main>\n    <footer>2026 · Web Service Development</footer>\n  </body>\n</html>\n",
