  "portfolio/en/index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>My Portfolio</title>\n    <meta\n      name=\"description\"\n      content=\"A personal site built with HTML, CSS and JavaScript\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n  <body>\n    <header>\n      <strong>MY PORTFOLIO</strong>\n      <nav aria-label=\"Projects\">\n        <a href=\"./index.html\">Home</a>\n        <a href=\"./about.html\">About</a>\n        <a href=\"./projects.html\">Projects</a>\n      </nav>\n    </header>\n    <main>\n      <h1>My Portfolio</h1>\n      <p>A personal site built with HTML, CSS and JavaScript</p>\n      <section>\n        <h2>Projects</h2>\n        <p>Timetable · Memo</p>\n        <a href=\"./projects.html?sort=date#featured\">Featured Projects</a>\n      </section>\n    </main>\n    <footer>2026 · Web Service Development</footer>\n  </body>\n</html>\n",
  "portfolio/en/projects.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Projects</title>\n    <meta\n      name=\"description\"\n      content=\"A personal site built with HTML, CSS and JavaScript\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <script src=\"./script.js\" defer></script>\n  </head>\n  <body>\n    <header>\n      <strong>MY PORTFOLIO</strong>\n      <nav aria-label=\"Projects\">\n        <a href=\"./index.html\">Home</a>\n        <a href=\"./about.html\">About</a>\n        <a href=\"./projects.html\">Projects</a>\n      </nav>\n    </header>\n    <main>\n      <h1>Projects</h1>\n      <section id=\"featured\">\n        <h2>Featured Projects</h2>\n        <div class=\"cards\">\n          <article>\n            <h3>Timetable</h3>\n            <p>A web project I built</p>\n          </article>\n          <article>\n            <h3>Memo</h3>\n            <p>A web project I built</p>\n          </article>\n        </div>\n      </section>\n      <section id=\"updates\">\n        <button id=\"add\" type=\"button\">Add Paragraph</button>\n      </section>\n    </main>\n    <footer>2026 · Web Service Development</footer>\n  </body>\n</html>\n",
  "portfolio/en/script.js": "const intro = document.querySelector('#intro');\nconst button = document.querySelector('#change');\n\nif (button) {\n  button.addEventListener('click', () => {\n    intro.textContent = 'Building my first website.';\n  });\n}\n\nconst add = document.querySelector('#add');\nif (add) {\n  add.addEventListener('click', () => {\n    const paragraph = document.createElement('p');\n    paragraph.textContent = 'Preparing a new project.';\n    document.querySelector('#updates').appendChild(paragraph);\n  });\n}\n",
  "portfolio/en/style.css": "* {\n  box-sizing: border-box;\n}\nbody {\n  margin: 0;\n  color: #333;\n  font:\n    16px/1.6 Arial,\n    sans-serif;\n  background: #fff;\n}\nheader,\nmain,\nfooter {\n  max-width: 760px;\n  margin: auto;\n  padding: 24px;\n}\nheader {\n  border-bottom: 1px solid #d5dfd7;\n}\nheader strong {\n  color: #1f6b4a;\n  letter-spacing: 0.08em;\n  font-size: 13px;\n}\nnav {\n  display: flex;\n  gap: 24px;\n  margin-top: 12px;\n}\na {\n  color: #1f6b4a;\n  text-underline-offset: 4px;\n}\nh1 {\n  margin: 0 0 16px;\n  font-size: 28px;\n  line-height: 1.3;\n}\nh2 {\n  margin: 0 0 8px;\n  font-size: 21px;\n}\np {\n  margin: 0 0 16px;\n}\nsection,\narticle {\n  margin-bottom: 20px;\n}\n.profile {\n  width: 360px;\n  max-width: 100%;\n  padding: 24px;\n  background: #f0f3ef;\n  border-radius: 8px;\n}\n.profile p {\n  margin-bottom: 16px;\n}\nbutton {\n  padding: 10px 16px;\n  border: 0;\n  border-radius: 4px;\n  background: #1f6b4a;\n  color: white;\n  font: inherit;\n  cursor: pointer;\n}\nbutton:focus-visible,\na:focus-visible {\n  outline: 3px solid #9a351f;\n  outline-offset: 3px;\n}\nbutton:hover {\n  background: #174f37;\n}\nbutton:disabled {\n  opacity: 0.6;\n  cursor: default;\n}\n.cards {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 16px;\n}\n.cards article {\n  padding: 20px;\n  border: 1px solid #d5dfd7;\n  border-radius: 8px;\n}\nfooter {\n  color: #596a60;\n  border-top: 1px solid #d5dfd7;\n  font-size: 13px;\n}\n.tools {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n  margin: 20px 0;\n}\n.tools button {\n  font-size: 13px;\n}\n.note {\n  color: #596a60;\n  font-size: 14px;\n}\n.measure {\n  width: 360px;\n  max-width: 100%;\n}\n.measure img {\n  display: block;\n  width: 100%;\n  height: auto;\n}\n.measure p {\n  padding: 16px;\n  background: #f0f3ef;\n}\n.tree {\n  font-family: monospace;\n  white-space: pre;\n}\n@media (max-width: 480px) {\n  .cards {\n    grid-template-columns: 1fr;\n  }\n  header,\n  main,\n  footer {\n    padding: 20px;\n  }\n}\n",
  "portfolio/index.html": "<!doctype html>\n<html lang=\"ko\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>나의 포트폴리오</title>\n    <meta\n      name=\"description\"\n      content=\"HTML · CSS · JavaScript로 만든 개인 사이트\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n  </head>\n  <body>\n    <header>\n      <strong>MY PORTFOLIO</strong>\n      <nav aria-label=\"프로젝트\">\n        <a href=\"./index.html\">홈</a>\n        <a href=\"./about.html\">소개</a>\n        <a href=\"./projects.html\">프로젝트</a>\n      </nav>\n    </header>\n    <main>\n      <h1>나의 포트폴리오</h1>\n      <p>HTML · CSS · JavaScript로 만든 개인 사이트</p>\n      <section>\n        <h2>프로젝트</h2>\n        <p>Timetable · Memo</p>\n        <a href=\"./projects.html?sort=date#featured\">대표 프로젝트</a>\n      </section>\n    </main>\n    <footer>2026 · 웹서비스개발</footer>\n  </body>\n</html>\n",
  "portfolio/projects.html": "<!doctype html>\n<html lang=\"ko\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>프로젝트</title>\n    <meta\n      name=\"description\"\n      content=\"HTML · CSS · JavaScript로 만든 개인 사이트\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <script src=\"./script.js\" defer></script>\n  </head>\n  <body>\n    <header>\n      <strong>MY PORTFOLIO</strong>\n      <nav aria-label=\"프로젝트\">\n        <a href=\"./index.html\">홈</a>\n        <a href=\"./about.html\">소개</a>\n        <a href=\"./projects.html\">프로젝트</a>\n      </nav>\n    </header>\n    <main>\n      <h1>프로젝트</h1>\n      <section id=\"featured\">\n        <h2>대표 프로젝트</h2>\n        <div class=\"cards\">\n          <article>\n            <h3>Timetable</h3>\n            <p>직접 만든 웹 프로젝트</p>\n          </article>\n          <article>\n            <h3>Memo</h3>\n            <p>직접 만든 웹 프로젝트</p>\n          </article>\n        </div>\n      </section>\n      <section id=\"updates\">\n        <button id=\"add\" type=\"button\">문단 추가</button>\n      </section>\n    </main>\n    <footer>2026 · 웹서비스개발</footer>\n  </body>\n</html>\n",
  "portfolio/script.js": "const intro = document.querySelector('#intro');\nconst button = document.querySelector('#change');\n\nif (button) {\n  button.addEventListener('click', () => {\n    intro.textContent = '나의 첫 웹사이트 제작 중';\n  });\n}\n\nconst add = document.querySelector('#add');\nif (add) {\n  add.addEventListener('click', () => {\n    const paragraph = document.createElement('p');\n    paragraph.textContent = '새 프로젝트를 준비 중';\n    document.querySelector('#updates').appendChild(paragraph);\n  });\n}\n",
