  "rendering/cascade.html": "<!doctype html>\n<html lang=\"ko\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>CSS · 자기소개</title>\n    <meta\n      name=\"description\"\n      content=\"HTML · CSS · JavaScript로 만든 개인 사이트\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <link rel=\"stylesheet\" href=\"./cascade.css\" />\n  </head>\n  <body>\n    <main>\n      <section class=\"profile\">\n        <h1>자기소개</h1>\n        <p id=\"intro\" aria-live=\"polite\">웹 개발 학습 중</p>\n        <button id=\"change\" type=\"button\">소개 바꾸기</button>\n      </section>\n    </main>\n  </body>\n</html>\n",
  "rendering/en/cascade.css": "body {\n  color: #333;\n}\n#intro {\n  color: #9a351f;\n}\n",
  "rendering/en/cascade.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>CSS · About Me</title>\n    <meta\n      name=\"description\"\n      content=\"A personal site built with HTML, CSS and JavaScript\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <link rel=\"stylesheet\" href=\"./cascade.css\" />\n  </head>\n  <body>\n    <main>\n      <section class=\"profile\">\n        <h1>About Me</h1>\n        <p id=\"intro\" aria-live=\"polite\">Learning web development.</p>\n        <button id=\"change\" type=\"button\">Change Introduction</button>\n      </section>\n    </main>\n  </body>\n</html>\n",
  "rendering/en/image-reserved.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Reserved Image Space</title>\n    <meta\n      name=\"description\"\n      content=\"A personal site built with HTML, CSS and JavaScript\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <script src=\"./image.js\" defer></script>\n  </head>\n  <body>\n    <main>\n      <h1>Reserved Image Space</h1>\n      <div class=\"measure\">\n        <img id=\"hero\" width=\"360\" height=\"180\" alt=\"Project illustration\" />\n        <p>The paragraph after the image</p>\n      </div>\n      <button id=\"load\" type=\"button\">Load Image</button>\n      <p class=\"note\">width=\"360\" height=\"180\"</p>\n    </main>\n  </body>\n</html>\n",
  "rendering/en/image-unreserved.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Reserved Image Space</title>\n    <meta\n      name=\"description\"\n      content=\"A personal site built with HTML, CSS and JavaScript\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <script src=\"./image.js\" defer></script>\n  </head>\n  <body>\n    <main>\n      <h1>Reserved Image Space</h1>\n      <div class=\"measure\">\n        <img id=\"hero\" alt=\"Project illustration\" />\n        <p>The paragraph after the image</p>\n      </div>\n      <button id=\"load\" type=\"button\">Load Image</button>\n      <p class=\"note\">width / height: —</p>\n    </main>\n  </body>\n</html>\n",
  "rendering/en/image.js": "const image = document.querySelector('#hero');\ndocument.querySelector('#load').addEventListener('click', () => {\n  setTimeout(() => {\n    image.src = './banner.svg';\n  }, 800);\n});\n",
  "rendering/en/index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>Rendering Experiments</title>\n    <meta\n      name=\"description\"\n      content=\"A personal site built with HTML, CSS and JavaScript\"\n    />\n    <link rel=\"stylesheet\" href=\"./style.css\" />\n    <script src=\"./rendering.js\" defer></script>\n  </head>\n  <body>\n    <main>\n      <h1>Rendering Experiments</h1>\n      <section class=\"profile\">\n        <h1>About Me</h1>\n        <p id=\"intro\" aria-live=\"polite\">Building my first website.</p>\n        <button id=\"change\" type=\"button\">Change Introduction</button>\n      </section>\n      <div class=\"tools\">\n        <button id=\"width\" type=\"button\">Change Width</button>\n        <button id=\"color\" type=\"button\">Change Background</button>\n        <button id=\"hide\" type=\"button\">Hide Paragraph</button>\n        <button id=\"reset\" type=\"button\">Reset</button>\n      </div>\n      <p class=\"note\">\n        width: 360px → 220px · background-color: #f0f3ef → #dceaf5\n      </p>\n    </main>\n  </body>\n</html>\n",
  "rendering/en/rendering.js": "const profile = document.querySelector('.profile');\nconst intro = document.querySelector('#intro');\n\ndocument.querySelector('#width').addEventListener('click', () => {\n  performance.mark('change-width');\n  profile.style.width = '220px';\n});\n\ndocument.querySelector('#color').addEventListener('click', () => {\n  performance.mark('change-background');\n  profile.style.backgroundColor = '#dceaf5';\n});\n\ndocument.querySelector('#change').addEventListener('click', () => {\n  intro.textContent = 'Learning web development.';\n});\n\ndocument.querySelector('#hide').addEventListener('click', () => {\n  intro.style.display = 'none';\n});\n\ndocument.querySelector('#reset').addEventListener('click', () => {\n  location.reload();\n});\n",
